/** Bitwise / logical operations, available for `bool` and integer dtypes. */
trait BitOps[T]:
  def and(x: T, y: T): T
  def or(x: T, y: T): T
  def xor(x: T, y: T): T
  def not(x: T): T

object BitOps:
  given BitOps[Boolean] with
    def and(x: Boolean, y: Boolean): Boolean = x && y
    def or(x: Boolean, y: Boolean): Boolean = x || y
    def xor(x: Boolean, y: Boolean): Boolean = x ^ y
    def not(x: Boolean): Boolean = !x
  given fromInt[T](using d: IntDType[T]): BitOps[T] with
    def and(x: T, y: T): T = d.and(x, y)
    def or(x: T, y: T): T = d.or(x, y)
    def xor(x: T, y: T): T = d.xor(x, y)
    def not(x: T): T = d.invert(x)

/** Supplies a dtype for a type parameter, defaulting to `float64` when it is not
  * otherwise determined — so `np.zeros(3)` is a float array while
  * `np.zeros[Int](3)` is an int32 array.
  */
trait DefaultDType[T]:
  def dtype: DType[T]

object DefaultDType extends LowPriorityDefaultDType:
  given float64Default: DefaultDType[Double] with
    def dtype: DType[Double] = DType.Float64

trait LowPriorityDefaultDType:
  given fromDType[T](using d: DType[T]): DefaultDType[T] with
    def dtype: DType[T] = d
